// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ArgusV5RewardAccounting} from "./libraries/ArgusV5RewardAccounting.sol";

/// @title ArgusV5RewardedToken
/// @notice The Portal #8 launch token's REWARD LAYER: every transfer
///         checkpoints both parties, eligible supply is genuine circulating
///         holder supply, the hook accrues into it on every swap, and
///         holders are paid by PULL through the escrow. Phase 3 of the
///         scope, token side, standing on the accumulator PR #78 proved.
///
/// @dev ------------------------------------------------------------------
///      THE ONE CALLING DISCIPLINE THE ACCUMULATOR CANNOT ENFORCE
///      ------------------------------------------------------------------
///      PR #78's RM7 mutants exist to say: `retireActiveCarry` MUST run
///      before every eligible-cohort change, and conservation alone cannot
///      see a caller that forgets it. This contract is that caller, and the
///      discipline lives in exactly one place - {_update} retires before it
///      touches the eligible supply, on every path that changes it. The
///      mutant that deletes that call is this suite's RM7 twin.
///
///      ------------------------------------------------------------------
///      WHO IS EXCLUDED, AND WHEN THE LIST FREEZES
///      ------------------------------------------------------------------
///      Excluded addresses hold tokens without earning: the pool's own
///      inventory must dilute nobody (scope §3). The launch transaction
///      wires parts whose addresses exist at different moments (the token
///      deploys before the hook that needs its address), so the exclusion
///      list is written by the PORTAL between construction and {bindHook},
///      and {bindHook} FREEZES it - after that moment no address can be
///      added or removed, ever. A mutable exclusion list would be a lever
///      for reshaping who earns, which is exactly what this line's
///      fees-fixed-forever property forbids.
///
///      ------------------------------------------------------------------
///      WHAT THIS CONTRACT IS NOT
///      ------------------------------------------------------------------
///      Not the full launch token: no curve, no dev-buy plumbing, no
///      metadata registry - those are Portal-lifecycle concerns (Phase 5)
///      layered on this base. This is the layer whose correctness the
///      accumulator's guarantees depend on, shipped standalone so it can be
///      proven the way every other Portal #8 part was.
contract ArgusV5RewardedToken is ERC20 {
    using ArgusV5RewardAccounting for ArgusV5RewardAccounting.State;

    // ----------------------------------------------------------- immutables --

    // forge-lint: disable-start(screaming-snake-case-immutable)
    /// @notice The Portal: writes exclusions and binds the hook, once.
    address public immutable portal;
    // forge-lint: disable-end(screaming-snake-case-immutable)

    // -------------------------------------------------------------- storage --

    ArgusV5RewardAccounting.State private _rewards;

    /// @notice The accrual caller: the launch's hook. Zero until bound.
    address public hook;

    /// @notice The payer: consumes claims when it pays a holder. Zero until
    ///         bound alongside the hook.
    address public escrow;

    /// @notice The launch's LP vault, recorded so a permissionless liquidity
    ///         crank can prove the locker it was handed is THIS launch's and
    ///         not an attacker's look-alike. Zero until {bindHook} (audit
    ///         pass 6, HIGH-1).
    address public locker;

    /// @notice Addresses that hold without earning. Frozen at {bindHook}.
    /// @dev Set once in the constructor; read through {logo}.
    string private _logo;

    mapping(address account => bool excluded) public isExcluded;

    /// @notice Circulating holder supply: total minus every excluded
    ///         balance. THE denominator of every accrual.
    uint256 public eligibleSupply;

    // --------------------------------------------------------------- events --

    event Excluded(address indexed account);
    event HookBound(address indexed hook, address indexed escrow);
    event QuoteAccrued(uint256 quoteAmount, uint256 reclassifiedRaw);
    event ClaimConsumed(address indexed holder, uint256 amountRaw);

    // --------------------------------------------------------------- errors --

    error NotPortal();
    error NotHook();
    error NotEscrow();
    error AlreadyBound();
    error NotBound();
    error ZeroAddress();
    error ExclusionsFrozen();
    error AlreadyExcluded();

    // ---------------------------------------------------------- constructor --

    /// @param supply minted whole to the PORTAL, which is excluded from
    ///        birth - so `eligibleSupply` starts at ZERO and the first
    ///        accrual with no holders reclassifies rather than dividing by
    ///        a supply nobody holds.
    /// @dev `portal_` is an ARGUMENT, not msg.sender: the §12 byte split
    ///      moves construction into a parts factory, and the factory passes
    ///      its own caller through - so a Portal deploys parts bound to
    ///      ITSELF, and anyone else calling the factory gets parts bound to
    ///      themselves, which is harmless.
    constructor(string memory name_, string memory symbol_, uint256 supply, address portal_, string memory logo_)
        ERC20(name_, symbol_)
    {
        portal = portal_;
        _logo = logo_;
        isExcluded[portal_] = true;
        emit Excluded(portal_);
        isExcluded[address(0xdead)] = true;
        emit Excluded(address(0xdead));
        // address(0) needs no entry: mint and burn adjust eligibleSupply by
        // the OTHER party's status, and address(0) never holds a balance.
        _mint(portal_, supply);
    }

    // --------------------------------------------------------------- wiring --

    /// @notice Launch-transaction writes, Portal-only, until {bindHook}
    ///         freezes the list. Excluding an address that already holds
    ///         settles it first and removes its balance from the
    ///         denominator - the same checkpoint discipline as a transfer.
    function exclude(address account) external {
        if (msg.sender != portal) revert NotPortal();
        if (hook != address(0)) revert ExclusionsFrozen();
        if (account == address(0)) revert ZeroAddress();
        if (isExcluded[account]) revert AlreadyExcluded();

        uint256 bal = balanceOf(account);
        if (bal != 0) {
            _rewards.checkpoint(account, bal);
            _rewards.retireActiveCarry();
            eligibleSupply -= bal;
            _rewards.setEligibleSupply(eligibleSupply);
        }
        isExcluded[account] = true;
        emit Excluded(account);
    }

    /// @notice One shot: after this, the exclusion list is permanent, the
    ///         hook may accrue and the escrow may consume. Both named in
    ///         the same breath because a hook without a payer is a liability
    ///         ledger nobody can be paid from.
    error PlumbingNotExcluded(address account);

    /// @dev The bind takes the WHOLE plumbing set and requires every member
    ///      already excluded (audit 3.11): freezing the exclusion list is
    ///      only safe when the list is known-complete, and a launch that
    ///      forgot the PoolManager would have put the pool's entire
    ///      inventory in the dividend denominator, permanently. The caller
    ///      names the six; this contract refuses to freeze around a hole.
    function bindHook(
        address hook_,
        address escrow_,
        address poolManager_,
        address positionManager_,
        address locker_,
        address lockVault_
    ) external {
        if (msg.sender != portal) revert NotPortal();
        if (hook != address(0)) revert AlreadyBound();
        if (hook_ == address(0) || escrow_ == address(0)) revert ZeroAddress();
        address[6] memory plumbing = [hook_, escrow_, poolManager_, positionManager_, locker_, lockVault_];
        for (uint256 i; i < 6; ++i) {
            if (plumbing[i] == address(0) || !isExcluded[plumbing[i]]) {
                revert PlumbingNotExcluded(plumbing[i]);
            }
        }
        hook = hook_;
        escrow = escrow_;
        locker = locker_;
        emit HookBound(hook_, escrow_);
    }

    // -------------------------------------------------------------- accrual --

    /// @notice The hook's per-swap call: divide `quoteAmount` (raw quote
    ///         units) across the current eligible cohort, O(1). Returns
    ///         what could NOT be divided (accrued while nobody was
    ///         eligible) - the hook routes that to the treasury (Q10).
    function accrueQuoteReward(uint256 quoteAmount) external returns (uint256 reclassifiedRaw) {
        if (msg.sender != hook) revert NotHook();
        reclassifiedRaw = _rewards.accrue(quoteAmount);
        emit QuoteAccrued(quoteAmount, reclassifiedRaw);
    }

    /// @notice The escrow's claim call: settle `holder` and hand back
    ///         everything they are owed, in raw quote units. The escrow
    ///         pays; this contract only keeps the ledger.
    function consumeClaim(address holder) external returns (uint256 amountRaw) {
        if (msg.sender != escrow) revert NotEscrow();
        amountRaw = _rewards.consume(holder, _eligibleBalance(holder));
        emit ClaimConsumed(holder, amountRaw);
    }

    // ---------------------------------------------------------------- views --

    /// @notice The launch's image, fixed at birth. The same getter every earlier
    ///         Argus token exposes, so explorers and other sites read it unchanged.
    function logo() external view returns (string memory) {
        return _logo;
    }

    function pendingOf(address holder) external view returns (uint256 raw) {
        (raw,) = _rewards.pending(holder, _eligibleBalance(holder));
    }

    /// @notice The carry ledgers, exposed for the discipline's own test:
    ///         the header says retireActiveCarry MUST run before every
    ///         eligible-cohort change, and conservation alone cannot see a
    ///         caller that forgets it - these views can.
    function carryScaled() external view returns (uint256 active, uint256 retired) {
        return (_rewards.activeCarryScaled, _rewards.retiredCarryScaled);
    }

    function rawLiability() external view returns (uint256) {
        return _rewards.rawLiability();
    }

    // ------------------------------------------------------------ the update --

    /// @dev The reference's checkpoint shape, verbatim in structure: settle
    ///      both ELIGIBLE parties at their PRE-transfer balances, retire the
    ///      carry, then move the eligible supply by the flow's direction -
    ///      and only then let the balances change.
    function _update(address from, address to, uint256 value) internal override {
        bool fromEligible = from != address(0) && !isExcluded[from];
        bool toEligible = to != address(0) && !isExcluded[to];

        if (fromEligible) _rewards.checkpoint(from, balanceOf(from));
        if (toEligible) _rewards.checkpoint(to, balanceOf(to));

        // The cohort changes when value crosses the eligibility boundary in
        // either direction; inside the cohort (eligible -> eligible) the
        // denominator is untouched and the carry keeps riding.
        if (fromEligible != toEligible && value != 0) {
            _rewards.retireActiveCarry();
            if (toEligible) {
                eligibleSupply += value;
            } else {
                eligibleSupply -= value;
            }
            _rewards.setEligibleSupply(eligibleSupply);
        }

        super._update(from, to, value);
    }

    function _eligibleBalance(address holder) private view returns (uint256) {
        return isExcluded[holder] ? 0 : balanceOf(holder);
    }
}

