    uint256 internal constant MAX_ELIGIBLE_SUPPLY = 1e27;
    uint256 internal constant MAX_LIFETIME_QUOTE = type(uint112).max;

    struct Account {
        uint256 paidAccumulator;
        uint256 accruedRaw;
        uint256 fractionalScaled;
        uint256 withdrawnRaw;
    }

    struct State {
        uint256 eligibleSupply;
        uint256 cumulativeQuotePerEligibleToken;
        uint256 activeCarryScaled;
        uint256 retiredCarryScaled;
        uint256 totalAcceptedRaw;
        uint256 totalReclassifiedRaw;
        uint256 totalWithdrawnRaw;
        mapping(address => Account) accounts;
