        account.paidAccumulator = self.cumulativeQuotePerEligibleToken;
    }

    function retireActiveCarry(State storage self) internal {
        self.retiredCarryScaled += self.activeCarryScaled;
        self.activeCarryScaled = 0;
    }

    function setEligibleSupply(State storage self, uint256 newSupply) internal {
        if (newSupply > MAX_ELIGIBLE_SUPPLY) revert EligibleSupplyBound();
