        uint256 whole = FullMath.mulDiv(eligibleBalance, delta, SCALE);
        uint256 remainder = mulmod(eligibleBalance, delta, SCALE);
        uint256 combinedFraction = account.fractionalScaled + remainder;
        raw = account.accruedRaw + whole + combinedFraction / SCALE;
        fraction = combinedFraction % SCALE;
    }

    function rawLiability(State storage self) internal view returns (uint256) {
        return self.totalAcceptedRaw - self.totalReclassifiedRaw - self.totalWithdrawnRaw;
    }
}

